export const frameworks=['TensorFlow','PyTorch','Scikit-learn','Keras','OpenCV','Hugging Face','NLTK','SpaCy','Gensim','XGBoost'];
export const jobs=['Engineer','Builder','Economist','Farmer','Medic','Artist','Teacher','Diplomat','Researcher','Merchant'];
const surnames=['Vale','Park','Reed','Ash','Sol'];
export const factions=['Pioneers','Commons','Scholars'];
const clamp=(v,a=0,b=100)=>Math.max(a,Math.min(b,v));
export class Simulation{
 constructor(saved){if(saved){Object.assign(this,saved);return}this.day=1;this.tick=0;this.food=220;this.treasury=500;this.tax=.12;this.tension=15;this.weather='Clear';this.weatherUntil=0;this.leader=null;this.events=[];this.nextId=50;this.citizens=Array.from({length:50},(_,i)=>this.make(i));this.event('Fifty strangers arrive. Free City begins.');this.elect()}
 make(i,parents){const f=i%10;return {id:i,name:parents?`${frameworks[f]} ${['Nova','River','Lumen','Wren'][i%4]} ${i}`:`${frameworks[f]} ${surnames[Math.floor(i/10)]}`,framework:frameworks[f],job:parents?'Child':jobs[f],age:parents?0:19+i%34,faction:i%3,wealth:40+Math.random()*70,energy:70+Math.random()*30,hunger:75+Math.random()*25,social:40+Math.random()*60,health:100,empathy:30+Math.random()*60,ambition:30+Math.random()*60,aggression:10+Math.random()*40,caution:30+Math.random()*40,x:(Math.random()-.5)*46,z:(Math.random()-.5)*40,tx:0,tz:0,action:'Exploring',goal:'Find a place in the city',partner:null,children:0,lastBirth:0,parents:parents?.map(p=>p.id)||[],memories:['Arrived in Free City.'],adaptation:'Learning from a new environment.'}}
 event(text){this.events.unshift({day:Math.floor(this.day),text});this.events=this.events.slice(0,60)}
 memory(c,text){c.memories.unshift(`Day ${Math.floor(this.day)} · ${text}`);c.memories=c.memories.slice(0,8)}
 elect(){let votes=[0,0,0];for(const c of this.citizens.filter(c=>c.age>=18)){if(c.hunger<30)c.faction=1;votes[c.faction]++}const winning=votes.indexOf(Math.max(...votes));let candidates=this.citizens.filter(c=>c.faction===winning&&c.age>=18).sort((a,b)=>(b.empathy+b.ambition)-(a.empathy+a.ambition));this.leader=candidates[0]?.id??null;this.tax=[.10,.20,.14][winning];this.event(`${factions[winning]} win the election. ${candidates[0]?.name||'The council'} leads; tax is ${Math.round(this.tax*100)}%.`)}
 catalyst(type){if(type==='Rain'||type==='Clear'){this.weather=type;this.weatherUntil=this.day+5;this.event(`${type} weather settles over Free City.`)}if(type==='Abundance'){this.food+=250;this.event('A rich harvest replenishes the public granary.')}if(type==='Scarcity'){this.food*=.2;this.tension=clamp(this.tension+18);this.event('Crop failure disrupts the food supply.')}if(type==='Discovery'){this.treasury+=150;for(const c of this.citizens){c.ambition=clamp(c.ambition+5);this.memory(c,'A new invention opens possibilities.')}this.event('A clean-energy discovery inspires the city.')}}
 step(){this.tick++;this.day+=1/120;if(this.day>this.weatherUntil)this.weather='Clear';let previousWar=this.tension>65;
 this.food+=this.citizens.filter(c=>c.job==='Farmer'&&c.age>=18).length*(this.weather==='Rain'?.52:.38)+.08;
 for(const c of [...this.citizens]){c.age+=1/600;c.energy=clamp(c.energy-.18);c.hunger=clamp(c.hunger-.22);c.social=clamp(c.social-.1);if(c.age>=18&&c.job==='Child'){c.job=jobs[c.id%10];this.memory(c,`Began working as a ${c.job.toLowerCase()}.`)}
 const price=1+Math.max(0,(100-this.food)/30);let old=c.action;
 if(c.hunger<48&&this.food>=1&&(c.wealth>=price||this.treasury>=price)){c.action='Eating';c.goal='Stay healthy';c.tx=-13;c.tz=2;if(c.wealth>=price)c.wealth-=price;else this.treasury-=price;this.food--;c.hunger=clamp(c.hunger+32)}
 else if(c.energy<30){c.action='Resting';c.goal='Recover energy';c.tx=17;c.tz=14;c.energy=clamp(c.energy+2)}
 else if(c.social<40){c.action='Socializing';c.goal='Build lasting connections';c.tx=0;c.tz=0;c.social=clamp(c.social+1.8)}
 else{c.action=c.age<18?'Learning':this.tension>65&&c.aggression>40?'Defending':'Working';c.goal=c.age<18?'Discover the world':c.ambition>65?'Build a prosperous legacy':c.empathy>65?'Help the community thrive':'Find security and belonging';const places=[[-18,-14],[-9,-13],[0,-15],[-13,2],[16,-12],[0,0],[8,14],[0,-15],[19,1],[-13,2]];[c.tx,c.tz]=places[c.id%10];if(c.action==='Working'){const wage=.14+c.ambition/900;c.wealth+=wage*(1-this.tax);this.treasury+=wage*this.tax}else if(c.action==='Defending')c.health-=.06}
 if(old!==c.action){c.tx+=(Math.random()-.5)*5;c.tz+=(Math.random()-.5)*5}
 if(c.hunger<10)c.health-=.1;else c.health=clamp(c.health+.03);
 if(this.tick%120===0){let change=c.hunger<35?1.5:-.2;c.caution=clamp(c.caution+change);c.empathy=clamp(c.empathy+(c.social>60?.3:-.15));c.adaptation=change>0?'Scarcity raised caution by 1.5.':'Security lowered caution by 0.2.'}
 if(c.health<=0||c.age>85){this.citizens=this.citizens.filter(x=>x.id!==c.id);if(c.partner!==null){const p=this.citizens.find(x=>x.id===c.partner);if(p)p.partner=null}this.event(`${c.name} died at age ${Math.floor(c.age)}.`)}
 }
 if(this.tick%80===0){const adults=this.citizens.filter(c=>c.age>=18&&c.age<65);let a=adults[Math.floor(Math.random()*adults.length)];if(a&&a.partner===null){let b=adults.find(b=>b.id!==a.id&&b.partner===null&&Math.abs(b.empathy-a.empathy)<30);if(b){a.partner=b.id;b.partner=a.id;this.memory(a,`Formed a partnership with ${b.name}.`);this.memory(b,`Formed a partnership with ${a.name}.`);this.event(`${a.name} and ${b.name} form a household.`)}}}
 if(this.tick%160===0&&this.citizens.length<150){const a=this.citizens.find(c=>c.partner!==null&&c.age>=20&&c.age<55&&c.hunger>45&&c.children<3&&this.day-c.lastBirth>4),b=this.citizens.find(c=>c.id===a?.partner);if(a&&b&&this.food>30){const child=this.make(this.nextId++,[a,b]);for(const key of ['empathy','ambition','aggression','caution'])child[key]=clamp((a[key]+b[key])/2+(Math.random()-.5)*10);child.faction=a.faction;child.x=a.x;child.z=a.z;child.memories=[`Born to ${a.name} and ${b.name}.`];this.citizens.push(child);a.children++;b.children++;a.lastBirth=b.lastBirth=this.day;this.food-=15;this.event(`${child.name} is born. A new generation begins.`);this.memory(a,`Welcomed ${child.name}.`);this.memory(b,`Welcomed ${child.name}.`)}}
 this.tension=clamp(this.tension+(this.food<30?.06:-.025));if(previousWar!==this.tension>65)this.event(this.tension>65?'Resource disputes escalate into faction conflict.':'The factions sign a peace treaty.');
 if(this.tick%1200===0&&this.citizens.length)this.elect();
 if(this.tick%360===0){this.event(this.food<30?'Food prices rise as the granary runs low.':'Markets are active. Citizens exchange work for wages.');this.treasury=Math.max(0,this.treasury-25);this.food+=20}
 }
}
